
-- Run once, AFTER public.customers exists.
-- Review with the database owner first.
-- Adds an isolated schema; never recreates or deletes
-- the team's existing tables.

BEGIN;

CREATE SCHEMA erp;

CREATE TABLE erp.accounts (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Code" text NOT NULL UNIQUE,
    "Name" text NOT NULL,
    "Category" text NOT NULL CHECK (
        "Category" IN ('asset','liability','equity','revenue','expense')
    ),
    "Active" boolean NOT NULL DEFAULT true
);

CREATE TABLE erp.suppliers (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name" text NOT NULL,
    "Email" text,
    "Phone" text
);

CREATE TABLE erp.products (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Sku" text NOT NULL UNIQUE,
    "Name" text NOT NULL,
    "SalePrice" numeric(18,4) NOT NULL CHECK ("SalePrice" > 0),
    "Stock" numeric(18,4) NOT NULL DEFAULT 0 CHECK ("Stock" >= 0),
    "Reserved" numeric(18,4) NOT NULL DEFAULT 0
        CHECK ("Reserved" >= 0 AND "Reserved" <= "Stock"),
    "AverageCost" numeric(18,4) NOT NULL DEFAULT 0
        CHECK ("AverageCost" >= 0),
    "StockValue" numeric(18,4) NOT NULL DEFAULT 0
        CHECK ("StockValue" >= 0)
);

CREATE TABLE erp.documents (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Kind" text NOT NULL CHECK ("Kind" IN ('sale','purchase')),
    "Status" text NOT NULL CHECK (
        "Status" IN (
            'draft','reserved','ready','posted','cancelled','reversed'
        )
    ),
    "CustomerId" integer REFERENCES public.customers(id)
        ON DELETE RESTRICT,
    "SupplierId" integer REFERENCES erp.suppliers("Id")
        ON DELETE RESTRICT,
    "PartyName" text NOT NULL,
    "Date" date NOT NULL,
    "DueDate" date NOT NULL,
    "Reference" text NOT NULL,
    "LinesJson" text NOT NULL,
    "Net" numeric(18,4) NOT NULL CHECK ("Net" > 0),
    "Vat" numeric(18,4) NOT NULL CHECK ("Vat" >= 0),
    "Total" numeric(18,4) NOT NULL
        CHECK ("Total" = "Net" + "Vat"),
    CHECK ("DueDate" >= "Date"),
    CHECK (
        ("Kind" = 'sale'
         AND "CustomerId" IS NOT NULL
         AND "SupplierId" IS NULL)
        OR
        ("Kind" = 'purchase'
         AND "SupplierId" IS NOT NULL
         AND "CustomerId" IS NULL)
    )
);

CREATE TABLE erp.journals (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Date" date NOT NULL,
    "Description" text NOT NULL,
    "Source" text NOT NULL UNIQUE,
    "CreatedBy" text NOT NULL,
    "CreatedAt" timestamptz NOT NULL
);

CREATE TABLE erp.journal_lines (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "JournalEntryId" integer NOT NULL
        REFERENCES erp.journals("Id") ON DELETE RESTRICT,
    "AccountId" integer NOT NULL
        REFERENCES erp.accounts("Id") ON DELETE RESTRICT,
    "Debit" numeric(18,4) NOT NULL DEFAULT 0,
    "Credit" numeric(18,4) NOT NULL DEFAULT 0,
    CHECK (
        ("Debit" > 0 AND "Credit" = 0)
        OR
        ("Credit" > 0 AND "Debit" = 0)
    ),
    CHECK (
        "Debit" = round("Debit",2)
        AND "Credit" = round("Credit",2)
    )
);

CREATE INDEX ON erp.journal_lines("JournalEntryId");
CREATE INDEX ON erp.journal_lines("AccountId");

CREATE TABLE erp.payments (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "DocumentId" integer NOT NULL
        REFERENCES erp.documents("Id") ON DELETE RESTRICT,
    "Date" date NOT NULL,
    "Amount" numeric(18,4) NOT NULL CHECK ("Amount" > 0),
    "Method" text NOT NULL CHECK ("Method" IN ('cash','bank')),
    "Reference" text NOT NULL,
    "RequestId" uuid NOT NULL UNIQUE,
    "Reversed" boolean NOT NULL DEFAULT false
);

CREATE INDEX ON erp.payments("DocumentId");

CREATE TABLE erp.stock_movements (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "ProductId" integer NOT NULL
        REFERENCES erp.products("Id") ON DELETE RESTRICT,
    "DocumentId" integer NOT NULL
        REFERENCES erp.documents("Id") ON DELETE RESTRICT,
    "Date" date NOT NULL,
    "Quantity" numeric(18,4) NOT NULL CHECK ("Quantity" <> 0),
    "UnitCost" numeric(18,4) NOT NULL CHECK ("UnitCost" >= 0),
    "Value" numeric(18,4) NOT NULL
);

CREATE TABLE erp.users (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Username" text NOT NULL UNIQUE,
    "PasswordHash" text NOT NULL,
    "Role" text NOT NULL CHECK (
        "Role" IN ('admin','sales','warehouse','accountant')
    ),
    "Active" boolean NOT NULL DEFAULT true
);

CREATE TABLE erp.periods (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Start" date NOT NULL,
    "End" date NOT NULL,
    "Closed" boolean NOT NULL DEFAULT false,
    CHECK ("Start" <= "End")
);

