-- Deferred check sees the entire entry
-- after all its lines have been inserted.

CREATE FUNCTION erp.check_balance()
RETURNS trigger
LANGUAGE plpgsql
AS $$
DECLARE
    entry_id integer;
    n integer;
    difference numeric;
BEGIN
    IF TG_TABLE_NAME = 'journals' THEN
        entry_id := NEW."Id";
    ELSE
        entry_id := NEW."JournalEntryId";
    END IF;

    SELECT count(*),
           coalesce(sum("Debit" - "Credit"), 0)
    INTO n, difference
    FROM erp.journal_lines
    WHERE "JournalEntryId" = entry_id;

    IF n < 2 OR difference <> 0 THEN
        RAISE EXCEPTION
            'Journal must balance with at least two lines'
            USING ERRCODE = '23514';
    END IF;

    RETURN NULL;
END
$$;

CREATE CONSTRAINT TRIGGER balanced_journal
AFTER INSERT ON erp.journals
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION erp.check_balance();

CREATE CONSTRAINT TRIGGER balanced_lines
AFTER INSERT ON erp.journal_lines
DEFERRABLE INITIALLY DEFERRED
FOR EACH ROW
EXECUTE FUNCTION erp.check_balance();

CREATE FUNCTION erp.no_ledger_edit()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
    RAISE EXCEPTION
        'Posted ledger is immutable'
        USING ERRCODE = '23514';
END
$$;

CREATE TRIGGER immutable_journal
BEFORE UPDATE OR DELETE ON erp.journals
FOR EACH ROW
EXECUTE FUNCTION erp.no_ledger_edit();

CREATE TRIGGER immutable_lines
BEFORE UPDATE OR DELETE ON erp.journal_lines
FOR EACH ROW
EXECUTE FUNCTION erp.no_ledger_edit();

COMMIT;
